<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE html PUBLIC "-//W3C//DTD XHTML 1.1//EN" "http://www.w3.org/TR/xhtml11/DTD/xhtml11.dtd">
<html xmlns="http://www.w3.org/1999/xhtml" xml:lang="{{lang}}">
<head>
  <meta http-equiv="Content-Type" content="text/html; charset=utf-8" />
  <meta http-equiv="Content-Style-Type" content="text/css" />
  <meta name="generator" content="crowbook" />
  <title>{{title_raw}}</title>
  <link rel="stylesheet" type="text/css" href="stylesheet.css" />
</head>
<body>
  <h2 class="author">{{author}}</h2>
  <h1 class="title">{{title}}</h1>
  {% if has_subtitle%}<h2 class="subtitle">{{subtitle}}</h2>{% endif %}
  {% if has_autograph %}
  <div id = "autograph">
    {{autograph}}
  </div>
  {% endif %}
</body>
</html>

===== html.css.print =====
#page {
    display: block;
}

.chapter {
    page-break-before: always;
}

#menu {
    display: none;
}

#nav {
    display: none;
}
===== html.css.colors =====
/* Colors for the navigation menu (toc) */
nav {
    background: #dfcae6;
    color: black;
    border-right-color: black;
}

#nav a:link {
    color: black;
}

#nav a:visited {
    color: black;
}

/* Colors for top and footer */
#top {
    background-color: #444343;
    color: white;
}

footer {
    background-color: #444343;
    color: white;
}

footer a, #top a {
    color: #fc71ff;
}

footer a:hover, #top a:hover {
    color: #b743fe;
}

/* Additional elements, only use for proofreading */
/* Grammar error */
.grammar-error {
    color: red;
    text-decoration-line: underline;
    text-decoration-style: double;
/*    background: #d966ff;*/
}

.popup_footnote {
    background-color: #e8e897;
}
