//! Minimal template engine used for all of Crowbook's templates.
//!
//! Two dialects are supported, because LaTeX templates must avoid `{}`:
//!
//! * curly:  `{{ var }}`, `{% if cond %}` / `{% else %}` / `{% endif %}`
//! * angled: `<< var >>`, `<# if cond #>` / `<# else #>` / `<# endif #>`
//!
//! A condition is either a variable name, `not name`, or `name | eq: "value"`.
//! Tags are removed without any whitespace trimming: the text (including the
//! newline that follows a tag) is copied verbatim, which is what makes the
//! stock templates produce their characteristic blank lines.

use std::collections::HashMap;
use std::fmt;

#[derive(Clone, Debug, PartialEq)]
pub enum Value {
    Str(String),
    Bool(bool),
}

impl Value {
    fn truthy(&self) -> bool {
        match *self {
            Value::Bool(b) => b,
            Value::Str(ref s) => !s.is_empty(),
        }
    }

    fn as_str(&self) -> String {
        match *self {
            Value::Bool(b) => (if b { "true" } else { "false" }).to_owned(),
            Value::Str(ref s) => s.clone(),
        }
    }
}

impl From<String> for Value {
    fn from(s: String) -> Value {
        Value::Str(s)
    }
}
impl<'a> From<&'a str> for Value {
    fn from(s: &'a str) -> Value {
        Value::Str(s.to_owned())
    }
}
impl From<bool> for Value {
    fn from(b: bool) -> Value {
        Value::Bool(b)
    }
}

/// A set of variables handed to `Template::render`.
#[derive(Clone, Debug, Default)]
pub struct Context {
    map: HashMap<String, Value>,
}

impl Context {
    pub fn new() -> Context {
        Context {
            map: HashMap::new(),
        }
    }

    pub fn insert<V: Into<Value>>(&mut self, key: &str, value: V) -> &mut Context {
        self.map.insert(key.to_owned(), value.into());
        self
    }

    pub fn get(&self, key: &str) -> Option<&Value> {
        self.map.get(key)
    }

    pub fn contains(&self, key: &str) -> bool {
        self.map.contains_key(key)
    }
}

/// Error produced when rendering a template. Mimics the diagnostics of the
/// templating library Crowbook is built on, since they are user visible.
#[derive(Debug)]
pub struct TemplateError {
    kind: &'static str,
    line: usize,
    col: usize,
    len: usize,
    source_line: String,
    reason: String,
}

impl fmt::Display for TemplateError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        let num = format!("{}", self.line);
        let width = num.len() + 1;
        let pad = " ".repeat(width);
        writeln!(f, "{}", self.kind)?;
        writeln!(f)?;
        writeln!(f, "{}--> <anonymous>:{}:{}", pad, self.line, self.col)?;
        writeln!(f, "{}|", pad)?;
        writeln!(f, "{:>w$} | {}", num, self.source_line, w = width - 1)?;
        writeln!(
            f,
            "{}| {}{}",
            pad,
            " ".repeat(self.col - 1),
            "^".repeat(self.len)
        )?;
        writeln!(f, "{}|", pad)?;
        write!(f, "{}= reason: {}", pad, self.reason)
    }
}

#[derive(Clone, Copy, PartialEq)]
pub enum Dialect {
    Curly,
    Angled,
}

impl Dialect {
    fn var_open(self) -> &'static str {
        match self {
            Dialect::Curly => "{{",
            Dialect::Angled => "<<",
        }
    }
    fn var_close(self) -> &'static str {
        match self {
            Dialect::Curly => "}}",
            Dialect::Angled => ">>",
        }
    }
    fn block_open(self) -> &'static str {
        match self {
            Dialect::Curly => "{%",
            Dialect::Angled => "<#",
        }
    }
    fn block_close(self) -> &'static str {
        match self {
            Dialect::Curly => "%}",
            Dialect::Angled => "#>",
        }
    }
}

#[derive(Debug, Clone)]
enum Cond {
    Truthy(String),
    Falsy(String),
    Eq(String, String),
}

#[derive(Debug)]
enum Node {
    Text(String),
    /// variable name, byte offset of the name in the source, name length
    Var(String, usize, usize),
    If {
        cond: Cond,
        offset: usize,
        len: usize,
        then: Vec<Node>,
        other: Vec<Node>,
    },
}

pub struct Template {
    source: String,
    nodes: Vec<Node>,
}

struct Parser<'a> {
    src: &'a str,
    pos: usize,
    dialect: Dialect,
}

enum Piece {
    Node(Node),
    Else(usize),
    End(usize),
    Eof,
}

impl<'a> Parser<'a> {
    fn parse_seq(&mut self, stop_ok: bool) -> Result<(Vec<Node>, Piece), TemplateError> {
        let mut out = Vec::new();
        loop {
            match self.next_piece()? {
                Piece::Node(n) => out.push(n),
                other => {
                    if let Piece::Eof = other {
                        if !stop_ok {
                            return Ok((out, other));
                        }
                    }
                    return Ok((out, other));
                }
            }
        }
    }

    fn next_piece(&mut self) -> Result<Piece, TemplateError> {
        if self.pos >= self.src.len() {
            return Ok(Piece::Eof);
        }
        let rest = &self.src[self.pos..];
        let vo = self.dialect.var_open();
        let bo = self.dialect.block_open();
        let iv = rest.find(vo);
        let ib = rest.find(bo);
        let next = match (iv, ib) {
            (None, None) => None,
            (Some(a), None) => Some((a, true)),
            (None, Some(b)) => Some((b, false)),
            (Some(a), Some(b)) => {
                if a <= b {
                    Some((a, true))
                } else {
                    Some((b, false))
                }
            }
        };
        match next {
            None => {
                let text = rest.to_owned();
                self.pos = self.src.len();
                Ok(Piece::Node(Node::Text(text)))
            }
            Some((idx, is_var)) => {
                if idx > 0 {
                    let text = rest[..idx].to_owned();
                    self.pos += idx;
                    return Ok(Piece::Node(Node::Text(text)));
                }
                if is_var {
                    self.parse_var()
                } else {
                    self.parse_block()
                }
            }
        }
    }

    fn parse_var(&mut self) -> Result<Piece, TemplateError> {
        let open = self.dialect.var_open();
        let close = self.dialect.var_close();
        let start = self.pos + open.len();
        let rest = &self.src[start..];
        let end = match rest.find(close) {
            Some(e) => e,
            None => {
                return Err(self.error("parse error", self.pos, open.len(), "unclosed tag"));
            }
        };
        let inner = &rest[..end];
        let trimmed = inner.trim();
        let off = start + (inner.len() - inner.trim_start().len());
        self.pos = start + end + close.len();
        Ok(Piece::Node(Node::Var(
            trimmed.to_owned(),
            off,
            trimmed.len(),
        )))
    }

    fn parse_block(&mut self) -> Result<Piece, TemplateError> {
        let open = self.dialect.block_open();
        let close = self.dialect.block_close();
        let tag_start = self.pos;
        let start = self.pos + open.len();
        let rest = &self.src[start..];
        let end = match rest.find(close) {
            Some(e) => e,
            None => {
                return Err(self.error("parse error", self.pos, open.len(), "unclosed tag"));
            }
        };
        let inner = &rest[..end];
        self.pos = start + end + close.len();
        let body = inner.trim();
        if body == "else" {
            return Ok(Piece::Else(tag_start));
        }
        if body == "endif" || body == "endfor" {
            return Ok(Piece::End(tag_start));
        }
        if let Some(cond_src) = body.strip_prefix("if") {
            if !cond_src.is_empty() && !cond_src.starts_with(char::is_whitespace) {
                return Err(self.error(
                    "parse error",
                    tag_start + open.len(),
                    body.len(),
                    "unknown keyword",
                ));
            }
            let cond_src = cond_src.trim();
            // Offset of the first identifier inside the condition, for diagnostics.
            let cond_off = start + (inner.len() - inner.trim_start().len()) + 2;
            let cond_off = cond_off + (cond_src.len() - cond_src.trim_start().len());
            let (cond, name_off, name_len) = parse_cond(cond_src, cond_off);
            let (then, piece) = self.parse_seq(true)?;
            let mut other = Vec::new();
            match piece {
                Piece::Else(_) => {
                    let (els, piece2) = self.parse_seq(true)?;
                    other = els;
                    if let Piece::Eof = piece2 {
                        return Err(self.error(
                            "parse error",
                            tag_start + open.len(),
                            2,
                            "unclosed block",
                        ));
                    }
                }
                Piece::End(_) => {}
                Piece::Eof => {
                    return Err(self.error(
                        "parse error",
                        tag_start + open.len(),
                        2,
                        "unclosed block",
                    ));
                }
                Piece::Node(_) => unreachable!(),
            }
            return Ok(Piece::Node(Node::If {
                cond,
                offset: name_off,
                len: name_len,
                then,
                other,
            }));
        }
        Err(self.error(
            "parse error",
            start + (inner.len() - inner.trim_start().len()),
            body.len().max(1),
            "unknown keyword",
        ))
    }

    fn error(&self, kind: &'static str, offset: usize, len: usize, reason: &str) -> TemplateError {
        make_error(self.src, kind, offset, len, reason)
    }
}

fn parse_cond(src: &str, offset: usize) -> (Cond, usize, usize) {
    if let Some(rest) = src.strip_prefix("not") {
        if rest.starts_with(char::is_whitespace) {
            let name = rest.trim();
            let off = offset + 3 + (rest.len() - rest.trim_start().len());
            return (Cond::Falsy(name.to_owned()), off, name.len().max(1));
        }
    }
    if let Some(idx) = src.find('|') {
        let name = src[..idx].trim().to_owned();
        let filter = src[idx + 1..].trim();
        let value = match filter.strip_prefix("eq:") {
            Some(v) => v.trim().trim_matches('"').to_owned(),
            None => String::new(),
        };
        let len = name.len().max(1);
        return (Cond::Eq(name, value), offset, len);
    }
    let name = src.trim().to_owned();
    let len = name.len().max(1);
    (Cond::Truthy(name), offset, len)
}

fn make_error(
    src: &str,
    kind: &'static str,
    offset: usize,
    len: usize,
    reason: &str,
) -> TemplateError {
    let mut line = 1;
    let mut line_start = 0;
    for (i, c) in src.char_indices() {
        if i >= offset {
            break;
        }
        if c == '\n' {
            line += 1;
            line_start = i + 1;
        }
    }
    let line_end = src[line_start..]
        .find('\n')
        .map(|i| line_start + i)
        .unwrap_or(src.len());
    let source_line = src[line_start..line_end].to_owned();
    let col = src[line_start..offset].chars().count() + 1;
    TemplateError {
        kind,
        line,
        col,
        len,
        source_line,
        reason: reason.to_owned(),
    }
}

impl Template {
    pub fn compile(source: &str, dialect: Dialect) -> Result<Template, TemplateError> {
        let mut parser = Parser {
            src: source,
            pos: 0,
            dialect,
        };
        let (nodes, piece) = parser.parse_seq(false)?;
        match piece {
            Piece::Eof => {}
            Piece::Else(off) | Piece::End(off) => {
                return Err(make_error(
                    source,
                    "parse error",
                    off + dialect.block_open().len(),
                    2,
                    "unexpected keyword",
                ));
            }
            Piece::Node(_) => unreachable!(),
        }
        Ok(Template {
            source: source.to_owned(),
            nodes,
        })
    }

    pub fn render(&self, context: &Context) -> Result<String, TemplateError> {
        let mut out = String::new();
        self.render_nodes(&self.nodes, context, &mut out)?;
        Ok(out)
    }

    fn render_nodes(
        &self,
        nodes: &[Node],
        context: &Context,
        out: &mut String,
    ) -> Result<(), TemplateError> {
        for node in nodes {
            match *node {
                Node::Text(ref t) => out.push_str(t),
                Node::Var(ref name, off, len) => match context.get(name) {
                    Some(v) => out.push_str(&v.as_str()),
                    None => {
                        return Err(make_error(
                            &self.source,
                            "render error",
                            off,
                            len,
                            "not found in this scope",
                        ));
                    }
                },
                Node::If {
                    ref cond,
                    offset,
                    len,
                    ref then,
                    ref other,
                } => {
                    let name = match *cond {
                        Cond::Truthy(ref n) | Cond::Falsy(ref n) | Cond::Eq(ref n, _) => n,
                    };
                    let value = match context.get(name) {
                        Some(v) => v,
                        None => {
                            return Err(make_error(
                                &self.source,
                                "render error",
                                offset,
                                len,
                                "not found in this scope",
                            ));
                        }
                    };
                    let taken = match *cond {
                        Cond::Truthy(_) => value.truthy(),
                        Cond::Falsy(_) => !value.truthy(),
                        Cond::Eq(_, ref expected) => value.as_str() == *expected,
                    };
                    if taken {
                        self.render_nodes(then, context, out)?;
                    } else {
                        self.render_nodes(other, context, out)?;
                    }
                }
            }
        }
        Ok(())
    }
}

/// Convenience: compile and render in one step.
pub fn render(source: &str, dialect: Dialect, context: &Context) -> Result<String, TemplateError> {
    Template::compile(source, dialect)?.render(context)
}

