//! Typed access to the book options, and the `--list-options` listing.

use std::collections::HashMap;

use crate::error::{Error, Result};
use crate::optiondefs::{OptionDef, SECTIONS};

/// Old option names that are still accepted, with a warning, and the option
/// they should be replaced with.
pub const RENAMED: &[(&str, &str)] = &[
    ("html.top", "html.header"),
    ("html.bottom", "html.footer"),
    ("numbering", "rendering.num_depth"),
    ("autoclean", "input.autoclean"),
    ("temp_dir", "crowbook.temp_dir"),
    ("zip.command", "crowbook.zip.command"),
    ("html_dir.css", "html.css"),
    ("html_dir.print_css", "html.css.print"),
    ("html.print_css", "html.css.print"),
    ("html_dir.script", "html.js"),
    ("html.script", "html.js"),
    ("html_dir.template", "html.dir.template"),
    ("html_single.html", "html.standalone.template"),
    ("html_single.js", "html.standalone.js"),
    ("html_single.one_chapter", "html.standalone.one_chapter"),
    ("html.display_chapter", "html.standalone.one_chapter"),
    ("side_notes", "html.side_notes"),
    ("escape_nb_spaces", "html.escape_nb_spaces"),
    ("enable_yaml_blocks", "input.yaml_blocks"),
    ("use_initials", "rendering.initials"),
    ("initials", "rendering.initials"),
    ("display_toc", "rendering.inline_toc"),
    ("toc_name", "rendering.inline_toc.name"),
    ("numbering_template", "rendering.chapter_template"),
    ("chapter_template", "rendering.chapter.template"),
    ("rendering.chapter_template", "rendering.chapter.template"),
    ("input.autoclean", "input.clean"),
    ("input.smart_quotes", "input.clean.smart_quotes"),
    ("input.ligature.dashes", "input.clean.ligature.dashes"),
    ("input.ligature.guillemets", "input.clean.ligature.guillemets"),
    ("html.crowbook_link", "html.footer"),
    ("tex.paper_size", "tex.paper.size"),
    ("tex.font_size", "tex.font.size"),
    ("tex.short", "tex.class"),
    ("epub.chapter.template", "rendering.chapter.template"),
    ("epub.version", "epub.version"),
];

/// Option names that were removed and now produce an error.
pub const REMOVED: &[&str] = &[
    "nb_char",
    "tex.short",
    "crowbook.verbose",
    "html.as_text",
    "html.script",
    "epub.optional_hyphen",
    "rendering.inline_toc.name.name",
];

/// Options that are silently accepted but do nothing anymore.
pub const OBSOLETE: &[&str] = &[
    "output.odt",
    "output.proofread.html",
    "output.proofread.html.dir",
    "output.proofread.pdf",
    "output.proofread.tex",
    "proofread",
    "proofread.languagetool",
    "proofread.languagetool.port",
    "proofread.grammalecte",
    "proofread.grammalecte.port",
    "proofread.repetitions",
    "proofread.repetitions.max_distance",
    "proofread.repetitions.fuzzy",
    "proofread.repetitions.fuzzy.threshold",
    "proofread.repetitions.ignore_proper",
    "proofread.repetitions.threshold",
];

#[derive(Debug, Clone, PartialEq)]
pub enum BookOption {
    Bool(bool),
    Int(i32),
    Char(char),
    String(String),
    StringVec(Vec<String>),
    Path(String),
}

impl BookOption {
    pub fn as_bool(&self) -> Option<bool> {
        match *self {
            BookOption::Bool(b) => Some(b),
            _ => None,
        }
    }
    pub fn as_i32(&self) -> Option<i32> {
        match *self {
            BookOption::Int(i) => Some(i),
            _ => None,
        }
    }
    pub fn as_str(&self) -> Option<&str> {
        match *self {
            BookOption::String(ref s) | BookOption::Path(ref s) => Some(s),
            _ => None,
        }
    }
    pub fn as_slice(&self) -> Option<&[String]> {
        match *self {
            BookOption::StringVec(ref v) => Some(v),
            _ => None,
        }
    }
}

pub fn find(key: &str) -> Option<&'static OptionDef> {
    for &(_, opts) in SECTIONS {
        for opt in opts {
            if opt.key == key {
                return Some(opt);
            }
        }
    }
    None
}

pub fn all() -> impl Iterator<Item = &'static OptionDef> {
    SECTIONS.iter().flat_map(|&(_, opts)| opts.iter())
}

fn default_value(opt: &OptionDef) -> Option<String> {
    let d = opt.default_display;
    if d == "not set" {
        return None;
    }
    if d.len() >= 2 && d.starts_with('"') && d.ends_with('"') {
        return Some(d[1..d.len() - 1].replace("\\\\", "\\"));
    }
    Some(d.to_owned())
}

fn parse_value(opt: &OptionDef, value: &str) -> Result<BookOption> {
    match opt.type_name {
        "boolean" => match value.trim() {
            "true" | "yes" | "on" => Ok(BookOption::Bool(true)),
            "false" | "no" | "off" => Ok(BookOption::Bool(false)),
            other => Err(Error::book_option(format!(
                "expected a boolean, found: {other}"
            ))),
        },
        "integer" => match value.trim().parse::<i32>() {
            Ok(i) => Ok(BookOption::Int(i)),
            Err(_) => Err(Error::book_option(format!(
                "expected an integer, found: {}",
                value.trim()
            ))),
        },
        "char" => {
            let mut chars = value.trim().chars();
            match (chars.next(), chars.next()) {
                (Some(c), None) => Ok(BookOption::Char(c)),
                _ => Err(Error::book_option(format!(
                    "could not parse '{}' as a char: does not contain exactly one char",
                    value.trim()
                ))),
            }
        }
        "path" | "template path" => Ok(BookOption::Path(value.to_owned())),
        "list of strings" => Ok(BookOption::StringVec(
            value.split_whitespace().map(|s| s.to_owned()).collect(),
        )),
        _ => Ok(BookOption::String(value.to_owned())),
    }
}

/// The whole set of options for a book.
#[derive(Debug, Clone)]
pub struct BookOptions {
    map: HashMap<String, BookOption>,
    /// Directory of the book configuration file, used to resolve relative paths.
    pub root: String,
}

impl Default for BookOptions {
    fn default() -> Self {
        Self::new()
    }
}

impl BookOptions {
    pub fn new() -> BookOptions {
        let mut map = HashMap::new();
        for opt in all() {
            if let Some(d) = default_value(opt) {
                if let Ok(v) = parse_value(opt, &d) {
                    map.insert(opt.key.to_owned(), v);
                }
            }
        }
        BookOptions {
            map,
            root: String::new(),
        }
    }

    /// Set an option from its string representation. Returns the canonical key
    /// that was actually set, plus an optional deprecation warning.
    pub fn set(&mut self, key: &str, value: &str) -> Result<Option<String>> {
        let mut warning = None;
        let mut key = key.to_owned();
        if let Some(&(_, new)) = RENAMED.iter().find(|&&(old, new)| old == key && old != new) {
            warning = Some(crate::lang::msg2(
                "'{}' has been deprecated, you should now use '{}'",
                &key,
                new,
            ));
            key = new.to_owned();
        }
        if REMOVED.contains(&key.as_str()) {
            return Err(Error::book_option(crate::lang::msg1(
                "key '{}' has been deprecated.",
                &key,
            )));
        }
        if OBSOLETE.contains(&key.as_str()) {
            return Ok(None);
        }
        let opt = match find(&key) {
            Some(o) => o,
            None => {
                return Err(Error::book_option(crate::lang::msg1(
                    "unrecognized key '{}'",
                    &key,
                )))
            }
        };
        let parsed = parse_value(opt, value)?;
        self.map.insert(key, parsed);
        Ok(warning)
    }

    pub fn get(&self, key: &str) -> Option<&BookOption> {
        self.map.get(key)
    }

    pub fn is_set(&self, key: &str) -> bool {
        self.map.contains_key(key)
    }

    pub fn unset(&mut self, key: &str) {
        self.map.remove(key);
    }

    pub fn set_raw(&mut self, key: &str, value: BookOption) {
        self.map.insert(key.to_owned(), value);
    }

    pub fn bool(&self, key: &str) -> bool {
        self.map
            .get(key)
            .and_then(|v| v.as_bool())
            .unwrap_or(false)
    }

    pub fn int(&self, key: &str) -> Option<i32> {
        self.map.get(key).and_then(|v| v.as_i32())
    }

    pub fn str(&self, key: &str) -> Option<&str> {
        self.map.get(key).and_then(|v| v.as_str())
    }

    /// A string option, empty if unset.
    pub fn s(&self, key: &str) -> &str {
        self.str(key).unwrap_or("")
    }

    pub fn list(&self, key: &str) -> Option<&[String]> {
        self.map.get(key).and_then(|v| v.as_slice())
    }
}

/// Render the `--list-options` output.
pub fn list_options() -> String {
    let mut out = String::new();
    for &(section, opts) in SECTIONS {
        out.push_str(section);
        out.push('\n');
        for opt in opts {
            out.push_str(opt.key);
            out.push('\n');
            out.push_str(&format!(
                "  type: {} (default: {})\n",
                opt.type_name, opt.default_display
            ));
            out.push_str(&wrap(opt.description, 80, "  "));
        }
        out.push('\n');
    }
    out
}

/// Greedy word wrapping, keeping explicit newlines as hard breaks and
/// preserving runs of spaces.
fn wrap(text: &str, width: usize, indent: &str) -> String {
    let mut out = String::new();
    for paragraph in text.split('\n') {
        let mut line = String::from(indent);
        let mut has_word = false;
        for word in paragraph.split(' ') {
            let extra = if has_word { 1 + word.len() } else { word.len() };
            if has_word && line.chars().count() + extra > width {
                out.push_str(&line);
                out.push('\n');
                line = String::from(indent);
                line.push_str(word);
            } else {
                if has_word {
                    line.push(' ');
                }
                line.push_str(word);
            }
            has_word = true;
        }
        out.push_str(&line);
        out.push('\n');
    }
    out
}

