//! Runtime language selection and message translation.
//!
//! Two independent things are localized:
//!
//! * the messages Crowbook prints (selected with `-L`/`--lang` or `$LANG`);
//!   only French is translated, everything else falls back to English;
//! * the strings that end up *inside* a generated book (selected by the book's
//!   `lang` option), see [`loc`].

use std::cell::RefCell;

thread_local! {
    static UI_LANG: RefCell<String> = const { RefCell::new(String::new()) };
}

/// Set the language used for Crowbook's own messages.
pub fn set_ui_lang(lang: &str) {
    let short = short_code(lang);
    UI_LANG.with(|l| *l.borrow_mut() = short);
}

/// Initialize the UI language from the environment.
pub fn init_from_env() {
    for var in ["LC_ALL", "LC_MESSAGES", "LANG"] {
        if let Ok(v) = std::env::var(var) {
            if !v.is_empty() && v != "C" && v != "POSIX" {
                set_ui_lang(&v);
                return;
            }
        }
    }
    set_ui_lang("en");
}

fn ui_lang() -> String {
    UI_LANG.with(|l| l.borrow().clone())
}

/// Normalize a locale string such as `fr_FR.UTF-8` to `fr`.
pub fn short_code(lang: &str) -> String {
    let lang = lang.trim();
    let cut = lang
        .find(['_', '-', '.', '@'])
        .unwrap_or(lang.len());
    lang[..cut].to_lowercase()
}

/// The French translation of Crowbook's messages, keyed by the English text.
const FRENCH: &[(&str, &str)] = &[
    (
        "Could not find file '{}' for {}",
        "Impossible de trouver le fichier '{}' pour {}",
    ),
    (
        "You must pass the name of a book configuration file.",
        "You must pass the name of a book configuration file.",
    ),
    (
        "Error converting BookOption: {}",
        "Erreur en convertissant l'option de livre :{}",
    ),
    (
        "Error during temporary files editing: {}",
        "Erreur durant l'édition de fichiers temporaires :{}",
    ),
    ("Error rendering {}: {}", "Erreur dans le rendu de {}: {}"),
    (
        "Error parsing config file: {}",
        "Erreur en analysant le fichier de configuration :{}",
    ),
    (
        "Error parsing markdown: {}",
        "Erreur en analysant le markdown :{}",
    ),
    ("Error compiling template: {}", "Erreur en compilant le patron :{}"),
    ("Error during zipping: {}", "Erreur pendant la compression :{}"),
    (
        "Crowbook exited successfully, but the following errors occurred:",
        "Crowbook s'est terminé avec succès, mais les erreurs suivantes se sont produites :",
    ),
    (
        "Could not run zip command, falling back to zip library",
        "Impossible d'exécuter la commande zip, utilisation de la bibliothèque zip",
    ),
    ("{} is not a valid template name", "{} n'est pas un nom de patron valide"),
    ("Attempting to generate {}...", "Tentative de génération de {}..."),
    ("Successfully generated {}: {}", "{} généré avec succès : {}"),
    ("Ignoring YAML block:\n{}", "Bloc YAML ignoré :\n{}"),
    (
        "Book {} already exists",
        "Le livre {} existe déjà",
    ),
    ("Created {}, now you'll have to complete it!",
     "{} créé, à vous de le compléter !"),
];

fn translate(msgid: &str) -> &str {
    if ui_lang() == "fr" {
        for &(en, fr) in FRENCH {
            if en == msgid {
                return fr;
            }
        }
    }
    msgid
}

fn subst(template: &str, args: &[&str]) -> String {
    let mut out = String::new();
    let mut rest = template;
    let mut i = 0;
    while let Some(pos) = rest.find("{}") {
        out.push_str(&rest[..pos]);
        if i < args.len() {
            out.push_str(args[i]);
        } else {
            out.push_str("{}");
        }
        i += 1;
        rest = &rest[pos + 2..];
    }
    out.push_str(rest);
    out
}

pub fn msg(msgid: &str) -> String {
    translate(msgid).to_owned()
}

pub fn msg1(msgid: &str, a: &str) -> String {
    subst(translate(msgid), &[a])
}

pub fn msg2(msgid: &str, a: &str, b: &str) -> String {
    subst(translate(msgid), &[a, b])
}

pub fn msg3(msgid: &str, a: &str, b: &str, c: &str) -> String {
    subst(translate(msgid), &[a, b, c])
}

// ---------------------------------------------------------------------------
// Strings that appear inside generated books
// ---------------------------------------------------------------------------

/// Keys used for book strings.
pub const CHAPTER: &str = "chapter";
pub const PART: &str = "part";
pub const TOC: &str = "toc";
