        toc: "Table des matières",
        title: "Titre",
        cover: "Couverture",
        notes: "Notes",
        display_all: "Afficher tous les chapitres",
        display_one: "Afficher un seul chapitre",
    },
    BookLang {
        code: "es",
        chapter: "Capítulo",
        part: "Parte",
        toc: "Tabla de contenidos",
        title: "Título",
        cover: "Cubierta",
        notes: "Notas",
        display_all: "Mostrar todos los capítulos",
        display_one: "Mostrar un capítulo",
    },
    BookLang {
        code: "de",
        chapter: "Kapitel",
        part: "Teil",
        toc: "Inhaltsverzeichnis",
        title: "Titel",
        cover: "Umschlag",
        notes: "Notizen",
        display_all: "Alle Kapitel anzeigen",
        display_one: "Ein Kapitel anzeigen",
    },
    BookLang {
        code: "ru",
        chapter: "Глава",
        part: "Часть",
        toc: "Содержание",
        title: "Название",
        cover: "Обложка",
        notes: "Заметки",
        display_all: "Показать все главы",
        display_one: "Показать одну главу",
    },
    BookLang {
        code: "ca",
        chapter: "Capítol",
        part: "Part",
        toc: "Índex",
        title: "Títol",
        cover: "Cobertura",
        notes: "Notes",
        display_all: "Mostrar tots els capítols",
        display_one: "Mostrar un capítol",
    },
];

fn book_lang(lang: &str) -> &'static BookLang {
    let short = short_code(lang);
    LANGS
        .iter()
        .find(|l| l.code == short)
        .unwrap_or(&LANGS[0])
}

/// Look up a book string for a given book language.
pub fn loc(lang: &str, key: &str) -> &'static str {
    let l = book_lang(lang);
    match key {
        CHAPTER => l.chapter,
        PART => l.part,
        TOC => l.toc,
        TITLE => l.title,
        COVER => l.cover,
        NOTES => l.notes,
        DISPLAY_ALL => l.display_all,
        DISPLAY_ONE => l.display_one,
        _ => "",
    }
}

