//! Errors, and how they are displayed to the user.

use std::fmt;
use std::result;

use crate::lang;

/// Where an error was detected, when we know.
#[derive(Debug, Clone, PartialEq)]
pub enum Source {
    Empty,
    File(String),
    Line(String, u32),
}

impl Source {
    pub fn new(file: &str) -> Source {
        Source::File(file.to_owned())
    }

    pub fn line(file: &str, line: u32) -> Source {
        Source::Line(file.to_owned(), line)
    }

    fn prefix(&self) -> String {
        match *self {
            Source::Empty => String::new(),
            Source::File(ref f) => format!("{f}: "),
            Source::Line(ref f, l) => format!("{f}:{l}: "),
        }
    }
}

#[derive(Debug)]
enum Kind {
    /// A file could not be found; carries the file and what it was needed for.
    FileNotFound(String, String),
    Parser(String),
    ConfigParser(String),
    BookOption(String),
    Render(String),
    Template(String),
    Zipper(String),
    Default(String),
    Invalid(String),
}

#[derive(Debug)]
pub struct Error {
    source: Source,
    kind: Kind,
}

pub type Result<T> = result::Result<T, Error>;

impl Error {
    fn new(kind: Kind) -> Error {
        Error {
            source: Source::Empty,
            kind,
        }
    }

    pub fn file_not_found(kind: &str, file: &str) -> Error {
        Error::new(Kind::FileNotFound(file.to_owned(), kind.to_owned()))
    }

    pub fn parser<S: Into<String>>(msg: S) -> Error {
        Error::new(Kind::Parser(msg.into()))
    }

    pub fn config_parser<S: Into<String>>(msg: S) -> Error {
        Error::new(Kind::ConfigParser(msg.into()))
    }

