//! Message output.
//!
//! Crowbook has three output styles:
//!
//! * the default "fancy" one, which hides info-level messages and gathers
//!   warnings and errors to display them once everything is done;
//! * `--no-fancy`, which prints `[LEVEL] message` as things happen;
//! * `--verbose`, which additionally prints debug messages with a timestamp.

use std::cell::RefCell;
use std::io::Write;

use crate::lang;

#[derive(Clone, Copy, PartialEq, PartialOrd, Debug)]
pub enum Level {
    Debug,
    Info,
    Warn,
    Error,
}

impl Level {
    fn tag(self) -> &'static str {
        match self {
            Level::Debug => "DEBUG",
            Level::Info => "INFO",
            Level::Warn => "WARN",
            Level::Error => "ERROR",
        }
    }

    fn fancy_tag(self) -> &'static str {
        match self {
            Level::Debug => "DEBUG",
            Level::Info => "INFO",
            Level::Warn => "WARNING",
            Level::Error => "ERROR",
        }
    }
}

#[derive(Clone, Copy, PartialEq)]
pub enum Style {
    Fancy,
    Plain,
    Verbose,
}

struct State {
    style: Style,
    quiet: bool,
    pending: Vec<(Level, String)>,
    /// Thread-ish counter shown by the verbose style.
    counter: u32,
}

thread_local! {
    static STATE: RefCell<State> = RefCell::new(State {
        style: Style::Fancy,
        quiet: false,
        pending: Vec::new(),
        counter: 1,
    });
}

pub fn configure(style: Style, quiet: bool) {
    STATE.with(|s| {
        let mut s = s.borrow_mut();
        s.style = style;
        s.quiet = quiet;
    });
}

fn timestamp() -> String {
    // Seconds since the epoch, converted to a local-agnostic HH:MM:SS. The
    // reference implementation prints local time; we have no timezone
    // database, so UTC is used.
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    let secs = now % 86400;
    format!("{:02}:{:02}:{:02}", secs / 3600, (secs % 3600) / 60, secs % 60)
}

fn emit(line: &str) {
    let stderr = std::io::stderr();
    let mut lock = stderr.lock();
    let _ = writeln!(lock, "{line}");
}

pub fn banner() {
    STATE.with(|s| {
        if !s.borrow().quiet {
            emit(&format!("CROWBOOK {}", crate::VERSION));
        }
    });
}

/// Log a message.
pub fn log(level: Level, msg: &str) {
    log_target(level, "crowbook::book", msg);
}

pub fn log_target(level: Level, target: &str, msg: &str) {
    STATE.with(|s| {
        let mut s = s.borrow_mut();
        if s.quiet {
            return;
        }
        match s.style {
            Style::Verbose => {
                let prefix = if level == Level::Debug {
                    let c = s.counter;
                    format!("[{}] ({}) ", level.tag(), c)
                } else {
                    format!("[{}] ", level.tag())
                };
                emit(&format!("{} {}{}: {}", timestamp(), prefix, target, msg));
            }
            Style::Plain => {
                if level == Level::Debug {
                    return;
                }
                emit(&format!("[{}] {}", level.tag(), msg));
            }
            Style::Fancy => {
                if level <= Level::Info {
                    return;
                }
                s.pending.push((level, msg.to_owned()));
            }
        }
    });
}

pub fn debug(msg: &str) {
    log(Level::Debug, msg);
}
pub fn info(msg: &str) {
    log(Level::Info, msg);
}
pub fn warn(msg: &str) {
    log(Level::Warn, msg);
}
pub fn error(msg: &str) {
    log(Level::Error, msg);
}

/// A fatal error, printed immediately even in fancy mode.
pub fn fatal(msg: &str) {
    STATE.with(|s| {
        let s = s.borrow();
        if s.quiet {
            return;
        }
        match s.style {
            Style::Fancy => emit(&format!("{} {}", Level::Error.fancy_tag(), msg)),
            Style::Plain => emit(&format!("[{}] {}", Level::Error.tag(), msg)),
            Style::Verbose => emit(&format!(
                "{} [{}] crowbook::book: {}",
                timestamp(),
                Level::Error.tag(),
                msg
            )),
        }
    });
}

/// Flush the messages gathered by the fancy style.
pub fn finish() {
    STATE.with(|s| {
        let mut s = s.borrow_mut();
        if s.quiet || s.style != Style::Fancy || s.pending.is_empty() {
            s.pending.clear();
            return;
        }
        let pending = std::mem::take(&mut s.pending);
        drop(s);
        emit(&format!(
            "{} {}",
            Level::Warn.fancy_tag(),
            lang::msg("Crowbook exited successfully, but the following errors occurred:")
        ));
        for (level, msg) in pending {
            emit(&format!("{} {}", level.fancy_tag(), msg));
        }
    });
}

