//! The token tree that renderers consume.

#[derive(Debug, Clone, PartialEq)]
pub enum Token {
    /// Plain text.
    Str(String),
    Paragraph(Vec<Token>),
    /// Heading level (1-6) and content.
    Header(i32, Vec<Token>),
    Emphasis(Vec<Token>),
    Strong(Vec<Token>),
    Strikethrough(Vec<Token>),
    Superscript(Vec<Token>),
    Subscript(Vec<Token>),
    Code(Vec<Token>),
    BlockQuote(Vec<Token>),
    /// Language tag and raw content.
    CodeBlock(String, String),
    Rule,
    SoftBreak,
    HardBreak,
    List(Vec<Token>),
    /// Start index and items.
    OrderedList(usize, Vec<Token>),
    Item(Vec<Token>),
    /// `true` when the box is ticked.
    TaskItem(bool, Vec<Token>),
    /// Column alignments and rows.
    Table(Vec<Align>, Vec<Token>),
    TableHead(Vec<Token>),
    TableRow(Vec<Token>),
    TableCell(Vec<Token>),
    /// A footnote definition; the label and its content.
    FootnoteDefinition(String, Vec<Token>),
    FootnoteReference(String),
    /// url, title, content
    Link(String, String, Vec<Token>),
    Image(String, String, Vec<Token>),
    StandaloneImage(String, String, Vec<Token>),
    /// Raw HTML (rendered as text when `crowbook.html_as_text` is on).
    Html(String),
    /// Raw HTML block.
    HtmlBlock(String),
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Align {
    None,
    Left,
    Center,
    Right,
}

impl Token {
    pub fn inner(&self) -> Option<&[Token]> {
        match *self {
            Token::Paragraph(ref v)
            | Token::Header(_, ref v)
            | Token::Emphasis(ref v)
            | Token::Strong(ref v)
            | Token::Strikethrough(ref v)
            | Token::Superscript(ref v)
            | Token::Subscript(ref v)
            | Token::Code(ref v)
            | Token::BlockQuote(ref v)
            | Token::List(ref v)
            | Token::OrderedList(_, ref v)
            | Token::Item(ref v)
            | Token::TaskItem(_, ref v)
            | Token::Table(_, ref v)
            | Token::TableHead(ref v)
            | Token::TableRow(ref v)
            | Token::TableCell(ref v)
            | Token::FootnoteDefinition(_, ref v)
            | Token::Link(_, _, ref v)
            | Token::Image(_, _, ref v)
            | Token::StandaloneImage(_, _, ref v) => Some(v),
            _ => None,
        }
    }

    pub fn inner_mut(&mut self) -> Option<&mut Vec<Token>> {
        match *self {
            Token::Paragraph(ref mut v)
            | Token::Header(_, ref mut v)
            | Token::Emphasis(ref mut v)
            | Token::Strong(ref mut v)
            | Token::Strikethrough(ref mut v)
            | Token::Superscript(ref mut v)
            | Token::Subscript(ref mut v)
            | Token::Code(ref mut v)
            | Token::BlockQuote(ref mut v)
            | Token::List(ref mut v)
            | Token::OrderedList(_, ref mut v)
            | Token::Item(ref mut v)
            | Token::TaskItem(_, ref mut v)
            | Token::Table(_, ref mut v)
            | Token::TableHead(ref mut v)
            | Token::TableRow(ref mut v)
            | Token::TableCell(ref mut v)
            | Token::FootnoteDefinition(_, ref mut v)
            | Token::Link(_, _, ref mut v)
            | Token::Image(_, _, ref mut v)
            | Token::StandaloneImage(_, _, ref mut v) => Some(v),
            _ => None,
        }
    }

    /// Concatenate all the text contained in a token tree.
    pub fn text(&self) -> String {
        let mut out = String::new();
        self.collect_text(&mut out);
        out
    }

    fn collect_text(&self, out: &mut String) {
        match *self {
            Token::Str(ref s) => out.push_str(s),
            Token::CodeBlock(_, ref s) => out.push_str(s),
            Token::SoftBreak | Token::HardBreak => out.push(' '),
            _ => {
                if let Some(inner) = self.inner() {
                    for t in inner {
                        t.collect_text(out);
                    }
                }
            }
        }
    }

    pub fn is_str(&self) -> bool {
        matches!(*self, Token::Str(_))
    }

    /// Whether this token starts a new block in the output.
    pub fn is_container(&self) -> bool {
        matches!(
            *self,
            Token::Paragraph(_)
                | Token::Header(..)
                | Token::BlockQuote(_)
                | Token::CodeBlock(..)
                | Token::List(_)
                | Token::OrderedList(..)
                | Token::Table(..)
                | Token::Rule
        )
    }
}

/// Collect the text of a whole token list.
pub fn text_of(tokens: &[Token]) -> String {
    let mut out = String::new();
    for t in tokens {
        out.push_str(&t.text());
    }
    out
}

