//! A CommonMark-flavoured Markdown parser (with the GitHub extensions Crowbook
//! relies on: tables, footnotes, strikethrough, task lists, autolinks).

use std::collections::HashMap;

use crate::entities;
use crate::token::{Align, Token};

#[derive(Clone, Copy, Default)]
pub struct Features {
    /// `crowbook.markdown.superscript`
    pub superscript: bool,
}

pub struct Parser {
    features: Features,
    refs: HashMap<String, (String, String)>,
}

struct Line<'a> {
    raw: &'a str,
}

impl<'a> Line<'a> {
    fn indent(&self) -> usize {
        self.raw.len() - self.raw.trim_start_matches(' ').len()
    }
    fn is_blank(&self) -> bool {
        self.raw.trim().is_empty()
    }
    fn trimmed(&self) -> &'a str {
        self.raw.trim_start_matches(' ')
    }
}

fn expand_tabs(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let mut col = 0;
    for c in s.chars() {
        if c == '\t' {
            let n = 4 - (col % 4);
            for _ in 0..n {
                out.push(' ');
            }
            col += n;
        } else {
            out.push(c);
            col += 1;
        }
    }
    out
}

fn split_lines(input: &str) -> Vec<String> {
    let normalized = input.replace("\r\n", "\n").replace('\r', "\n");
    let mut lines: Vec<String> = normalized.split('\n').map(expand_tabs).collect();
    // A trailing newline does not create an extra empty line.
    if let Some(last) = lines.last() {
        if last.is_empty() {
            lines.pop();
        }
    }
    lines
}

impl Parser {
    pub fn new(features: Features) -> Parser {
        Parser {
            features,
            refs: HashMap::new(),
        }
    }

    pub fn parse(&mut self, input: &str) -> Vec<Token> {
        let owned = split_lines(input);
        let mut lines: Vec<Line> = owned.iter().map(|s| Line { raw: s }).collect();
        self.collect_refs(&mut lines);
        let mut tokens = self.parse_blocks(&lines);
        merge_strings(&mut tokens);
        promote_standalone_images(&mut tokens);
        tokens
    }

    /// Remove link reference definitions and remember them.
    fn collect_refs(&mut self, lines: &mut Vec<Line>) {
        let mut i = 0;
        let mut keep = Vec::new();
        let mut fenced: Option<String> = None;
        while i < lines.len() {
            let line = lines[i].raw;
            let trimmed = line.trim_start_matches(' ');
            if let Some(ref fence) = fenced {
                if trimmed.starts_with(fence.as_str()) {
                    fenced = None;
                }
                keep.push(i);
                i += 1;
                continue;
            }
            if lines[i].indent() < 4 {
                if let Some(f) = fence_marker(trimmed) {
                    fenced = Some(f);
                    keep.push(i);
                    i += 1;
                    continue;
                }
            }
            if lines[i].indent() < 4 && trimmed.starts_with('[') && !trimmed.starts_with("[^") {
                if let Some((label, url, title, consumed)) = parse_ref_def(lines, i) {
                    self.refs
                        .insert(label.to_lowercase(), (url, title));
                    i += consumed;
                    continue;
                }
            }
            keep.push(i);
            i += 1;
        }
        let mut new_lines = Vec::with_capacity(keep.len());
        for idx in keep {
            new_lines.push(Line { raw: lines[idx].raw });
        }
        *lines = new_lines;
    }

    fn parse_blocks(&mut self, lines: &[Line]) -> Vec<Token> {
        let mut out = Vec::new();
        let mut i = 0;
        while i < lines.len() {
            if lines[i].is_blank() {
                i += 1;
                continue;
            }
            let indent = lines[i].indent();
            let trimmed = lines[i].trimmed();

            if indent >= 4 {
                // Indented code block
                let mut content = String::new();
                while i < lines.len() {
                    if lines[i].is_blank() {
                        // Blank lines belong to the block only if code follows.
                        let mut j = i;
                        while j < lines.len() && lines[j].is_blank() {
                            j += 1;
                        }
                        if j < lines.len() && lines[j].indent() >= 4 {
                            for _ in i..j {
                                content.push('\n');
                            }
                            i = j;
                            continue;
                        }
                        break;
                    }
                    if lines[i].indent() < 4 {
                        break;
                    }
                    let raw = lines[i].raw;
                    content.push_str(&raw[4..]);
                    content.push('\n');
                    i += 1;
                }
                out.push(Token::CodeBlock(String::new(), content));
                continue;
            }

            if is_thematic_break(trimmed) {
                out.push(Token::Rule);
                i += 1;
                continue;
            }

            if let Some((level, content)) = atx_heading(trimmed) {
                out.push(Token::Header(level, self.parse_inline(&content)));
                i += 1;
                continue;
            }

            if let Some(fence) = fence_marker(trimmed) {
                let info = fence_info(trimmed, &fence);
                let mut content = String::new();
                i += 1;
                while i < lines.len() {
                    let t = lines[i].trimmed();
                    if lines[i].indent() < 4 && closes_fence(t, &fence) {
                        i += 1;
                        break;
                    }
                    let raw = lines[i].raw;
                    let strip = indent.min(raw.len() - raw.trim_start_matches(' ').len());
                    content.push_str(&raw[strip..]);
                    content.push('\n');
                    i += 1;
                }
                out.push(Token::CodeBlock(info, content));
                continue;
            }

            if trimmed.starts_with('>') {
                let mut inner: Vec<String> = Vec::new();
                while i < lines.len() {
                    let t = lines[i].trimmed();
                    if lines[i].indent() < 4 && t.starts_with('>') {
                        let rest = &t[1..];
                        let rest = rest.strip_prefix(' ').unwrap_or(rest);
                        inner.push(rest.to_owned());
                        i += 1;
                    } else if !lines[i].is_blank() && can_lazily_continue(lines, i) {
                        inner.push(lines[i].raw.to_owned());
                        i += 1;
                    } else {
                        break;
                    }
                }
                let sub: Vec<Line> = inner.iter().map(|s| Line { raw: s }).collect();
                let mut tokens = self.parse_blocks(&sub);
                merge_strings(&mut tokens);
                out.push(Token::BlockQuote(tokens));
                continue;
            }

            if let Some((label, consumed)) = footnote_def(lines, i) {
                let mut inner: Vec<String> = Vec::new();
                let first = lines[i].trimmed();
                let colon = first.find("]:").unwrap() + 2;
                let rest = first[colon..].trim_start();
                inner.push(rest.to_owned());
                for k in 1..consumed {
                    let raw = lines[i + k].raw;
                    let strip = raw.len().min(4);
                    let stripped = if raw.trim().is_empty() {
                        ""
                    } else if raw.starts_with("    ") {
                        &raw[strip..]
                    } else {
                        raw.trim_start_matches(' ')
                    };
                    inner.push(stripped.to_owned());
                }
                let sub: Vec<Line> = inner.iter().map(|s| Line { raw: s }).collect();
                let mut tokens = self.parse_blocks(&sub);
                merge_strings(&mut tokens);
                out.push(Token::FootnoteDefinition(label, tokens));
                i += consumed;
                continue;
            }

            if let Some(marker) = list_marker(trimmed) {
                let (token, consumed) = self.parse_list(lines, i, marker);
                out.push(token);
                i += consumed;
                continue;
            }

            if let Some((aligns, consumed)) = table_start(lines, i) {
                let (token, used) = self.parse_table(lines, i, aligns, consumed);
                out.push(token);
                i += used;
                continue;
            }

            if is_html_block_start(trimmed) {
                let mut content = String::new();
                while i < lines.len() && !lines[i].is_blank() {
                    content.push_str(lines[i].raw);
                    content.push('\n');
                    i += 1;
                }
                out.push(Token::HtmlBlock(content));
                continue;
            }

            // Paragraph (possibly closed by a setext underline).
            let mut para: Vec<String> = Vec::new();
            let mut level = 0;
            while i < lines.len() {
                if lines[i].is_blank() {
                    break;
                }
                let t = lines[i].trimmed();
                if !para.is_empty() {
                    if let Some(l) = setext_underline(t) {
                        if lines[i].indent() < 4 {
                            level = l;
                            i += 1;
                            break;
                        }
                    }
                    if lines[i].indent() < 4 && interrupts_paragraph(t) {
                        break;
                    }
                    if lines[i].indent() < 4 && table_start(lines, i).is_some() {
                        break;
                    }
                }
                para.push(lines[i].trimmed().trim_end().to_owned());
                i += 1;
            }
            let text = para.join("\n");
            let inline = self.parse_inline(&text);
            if level > 0 {
                out.push(Token::Header(level, inline));
            } else {
                out.push(Token::Paragraph(inline));
            }
        }
        out
    }

    fn parse_list(&mut self, lines: &[Line], start: usize, marker: Marker) -> (Token, usize) {
        let mut items: Vec<Token> = Vec::new();
        let mut i = start;
        let mut first = true;
        let mut start_index = marker.start;
        loop {
            if i >= lines.len() {
                break;
            }
            if lines[i].is_blank() {
                // A blank line only continues the list if the next non-blank
                // line belongs to it.
                let mut j = i;
                while j < lines.len() && lines[j].is_blank() {
                    j += 1;
                }
                if j >= lines.len() {
                    break;
                }
                let cont = lines[j].indent() >= marker.content_indent
                    || list_marker(lines[j].trimmed())
                        .map(|m| m.same_kind(&marker) && lines[j].indent() < 4)
                        .unwrap_or(false);
                if !cont {
                    break;
                }
                i = j;
                continue;
            }
            let cur = match list_marker(lines[i].trimmed()) {
                Some(m) if lines[i].indent() < marker.content_indent.max(1) => m,
                _ => break,
            };
            if !cur.same_kind(&marker) {
                break;
            }
            if first {
                start_index = cur.start;
                first = false;
            }
            // Gather this item's lines.
            let content_indent = lines[i].indent() + cur.content_offset;
            let mut inner: Vec<String> = Vec::new();
            let first_line = &lines[i].trimmed()[cur.width..];
            let first_line = if first_line.len() >= cur.spaces {
                &first_line[cur.spaces..]
            } else {
                first_line.trim_start_matches(' ')
            };
            inner.push(first_line.to_owned());
            i += 1;
            while i < lines.len() {
                if lines[i].is_blank() {
                    let mut j = i;
                    while j < lines.len() && lines[j].is_blank() {
                        j += 1;
                    }
                    if j < lines.len() && lines[j].indent() >= content_indent {
                        for _ in i..j {
                            inner.push(String::new());
                        }
                        i = j;
                        continue;
                    }
                    break;
                }
                if lines[i].indent() >= content_indent {
                    inner.push(lines[i].raw[content_indent..].to_owned());
                    i += 1;
                    continue;
                }
                if list_marker(lines[i].trimmed()).is_some() || interrupts_paragraph(lines[i].trimmed())
                {
                    break;
                }
                // Lazy continuation of the item's paragraph.
                inner.push(lines[i].trimmed().to_owned());
                i += 1;
            }
            let sub: Vec<Line> = inner.iter().map(|s| Line { raw: s }).collect();
            let mut tokens = self.parse_blocks(&sub);
            merge_strings(&mut tokens);
            // Task list markers are recognized at the start of the item.
            if let Some(checked) = task_marker(&mut tokens) {
                items.push(Token::TaskItem(checked, tokens));
            } else {
                items.push(Token::Item(tokens));
            }
        }
        let token = if marker.ordered {
            Token::OrderedList(start_index, items)
        } else {
            Token::List(items)
        };
        (token, i - start)
    }

    fn parse_table(
        &mut self,
        lines: &[Line],
        start: usize,
        aligns: Vec<Align>,
        _consumed: usize,
    ) -> (Token, usize) {
        let ncols = aligns.len();
        let mut rows = Vec::new();
        let header = split_row(lines[start].trimmed(), ncols);
        let mut head_cells = Vec::new();
        for cell in header {
            head_cells.push(Token::TableCell(self.parse_inline(cell.trim())));
        }
        rows.push(Token::TableHead(head_cells));
        let mut i = start + 2;
        while i < lines.len() {
            let t = lines[i].trimmed();
            if lines[i].is_blank() || !t.contains('|') && !t.starts_with('|') {
                break;
            }
            if lines[i].indent() >= 4 {
                break;
            }
            let cells = split_row(t, ncols);
            let mut row = Vec::new();
            for cell in cells {
                row.push(Token::TableCell(self.parse_inline(cell.trim())));
            }
            rows.push(Token::TableRow(row));
            i += 1;
        }
        (Token::Table(aligns, rows), i - start)
    }
}

#[derive(Clone, Copy)]
struct Marker {
    ordered: bool,
    delim: char,
    bullet: char,
    start: usize,
    /// Width of the marker itself (`-`, `1.`, ...).
    width: usize,
    /// Spaces after the marker.
    spaces: usize,
    content_offset: usize,
    content_indent: usize,
}

impl Marker {
    fn same_kind(&self, other: &Marker) -> bool {
        if self.ordered != other.ordered {
            return false;
        }
        if self.ordered {
            self.delim == other.delim
        } else {
            self.bullet == other.bullet
        }
    }
}

fn list_marker(s: &str) -> Option<Marker> {
    let bytes = s.as_bytes();
    if bytes.is_empty() {
        return None;
    }
    let (ordered, width, delim, bullet, start) = if bytes[0] == b'-'
        || bytes[0] == b'+'
        || bytes[0] == b'*'
    {
        (false, 1, ' ', bytes[0] as char, 1)
    } else if bytes[0].is_ascii_digit() {
        let mut n = 0;
        while n < bytes.len() && bytes[n].is_ascii_digit() && n < 9 {
            n += 1;
        }
        if n >= bytes.len() || (bytes[n] != b'.' && bytes[n] != b')') {
            return None;
        }
        let num: usize = s[..n].parse().unwrap_or(0);
        (true, n + 1, bytes[n] as char, ' ', num)
    } else {
        return None;
    };
    if s.len() == width {
        // Marker alone on its line: empty item.
        return Some(Marker {
            ordered,
            delim,
            bullet,
            start,
            width,
            spaces: 0,
            content_offset: width + 1,
            content_indent: width + 1,
        });
    }
    if s.as_bytes()[width] != b' ' {
        return None;
    }
    let rest = &s[width..];
    let spaces = rest.len() - rest.trim_start_matches(' ').len();
    let spaces = if spaces > 4 { 1 } else { spaces };
    Some(Marker {
        ordered,
        delim,
        bullet,
        start,
        width,
        spaces,
        content_offset: width + spaces,
        content_indent: width + spaces,
    })
}

fn task_marker(tokens: &mut [Token]) -> Option<bool> {
    if let Some(Token::Paragraph(ref mut inner)) = tokens.first_mut() {
        if let Some(Token::Str(ref mut s)) = inner.first_mut() {
            let lower = s.to_lowercase();
            if let Some(rest) = lower.strip_prefix("[ ] ") {
                let n = s.len() - rest.len();
                *s = s[n..].to_owned();
                return Some(false);
            }
            if lower.starts_with("[x] ") {
                *s = s[4..].to_owned();
                return Some(true);
            }
        }
    }
    None
}

fn is_thematic_break(s: &str) -> bool {
    let s = s.trim();
    if s.len() < 3 {
        return false;
    }
    let first = s.chars().next().unwrap();
    if first != '-' && first != '*' && first != '_' {
        return false;
    }
    let mut count = 0;
    for c in s.chars() {
        if c == first {
            count += 1;
        } else if c != ' ' {
            return false;
        }
    }
    count >= 3
}

fn atx_heading(s: &str) -> Option<(i32, String)> {
    if !s.starts_with('#') {
        return None;
    }
    let hashes = s.len() - s.trim_start_matches('#').len();
    if hashes > 6 {
        return None;
    }
    let rest = &s[hashes..];
    if !rest.is_empty() && !rest.starts_with(' ') {
        return None;
    }
    let mut content = rest.trim();
    // Optional closing sequence of #s
    if content.ends_with('#') {
        let trimmed = content.trim_end_matches('#');
        if trimmed.is_empty() || trimmed.ends_with(' ') {
            content = trimmed.trim_end();
        }
    }
    Some((hashes as i32, content.to_owned()))
}

fn setext_underline(s: &str) -> Option<i32> {
    let s = s.trim_end();
    if s.is_empty() {
        return None;
    }
    if s.chars().all(|c| c == '=') {
        return Some(1);
    }
    if s.chars().all(|c| c == '-') {
        return Some(2);
    }
    None
}

fn fence_marker(s: &str) -> Option<String> {
    for c in ['`', '~'] {
        let n = s.chars().take_while(|&x| x == c).count();
        if n >= 3 {
            return Some(std::iter::repeat(c).take(n).collect());
        }
    }
    None
}

fn fence_info(s: &str, fence: &str) -> String {
    let rest = &s[fence.len()..];
    rest.trim().split_whitespace().next().unwrap_or("").to_owned()
}

fn closes_fence(s: &str, fence: &str) -> bool {
    let c = fence.chars().next().unwrap();
    let n = s.chars().take_while(|&x| x == c).count();
    n >= fence.len() && s.trim_end().chars().all(|x| x == c)
}

fn interrupts_paragraph(s: &str) -> bool {
    if is_thematic_break(s) {
        return true;
    }
    if atx_heading(s).is_some() {
        return true;
    }
    if fence_marker(s).is_some() {
        return true;
    }
    if s.starts_with('>') {
        return true;
    }
    if is_html_block_start(s) {
        return true;
    }
    if let Some(m) = list_marker(s) {
        // Only a list that starts with 1 (or a bullet) can interrupt.
        if !m.ordered || m.start == 1 {
            return true;
        }
    }
    false
}

fn can_lazily_continue(lines: &[Line], i: usize) -> bool {
    let t = lines[i].trimmed();
    !interrupts_paragraph(t) && lines[i].indent() < 4
}

const HTML_BLOCK_TAGS: &[&str] = &[
    "address", "article", "aside", "base", "basefont", "blockquote", "body", "caption", "center",
    "col", "colgroup", "dd", "details", "dialog", "dir", "div", "dl", "dt", "fieldset",
    "figcaption", "figure", "footer", "form", "frame", "frameset", "h1", "h2", "h3", "h4", "h5",
    "h6", "head", "header", "hr", "html", "iframe", "legend", "li", "link", "main", "menu",
    "menuitem", "nav", "noframes", "ol", "optgroup", "option", "p", "param", "section", "source",
    "summary", "table", "tbody", "td", "tfoot", "th", "thead", "title", "tr", "track", "ul",
];

fn is_html_block_start(s: &str) -> bool {
    if !s.starts_with('<') {
        return false;
    }
    if s.starts_with("<!--") || s.starts_with("<?") || s.starts_with("<!") {
        return true;
    }
    let rest = s[1..].strip_prefix('/').unwrap_or(&s[1..]);
    let name: String = rest
        .chars()
        .take_while(|c| c.is_ascii_alphanumeric())
        .collect::<String>()
        .to_lowercase();
    if name.is_empty() {
        return false;
    }
    if HTML_BLOCK_TAGS.contains(&name.as_str()) {
        return true;
    }
    if name == "script" || name == "pre" || name == "style" || name == "textarea" {
        return true;
    }
    false
}

fn parse_ref_def(lines: &[Line], i: usize) -> Option<(String, String, String, usize)> {
    let line = lines[i].trimmed();
    let close = find_link_label_end(line)?;
    if !line[close + 1..].starts_with(':') {
        return None;
    }
    let label = line[1..close].trim().to_owned();
    if label.is_empty() {
        return None;
    }
    let mut rest = line[close + 2..].trim().to_owned();
    let mut consumed = 1;
    if rest.is_empty() {
        if i + 1 >= lines.len() || lines[i + 1].is_blank() {
            return None;
        }
        rest = lines[i + 1].trimmed().trim().to_owned();
        consumed = 2;
    }
    let mut parts = rest.splitn(2, char::is_whitespace);
    let url = parts.next().unwrap_or("").to_owned();
    if url.is_empty() {
        return None;
    }
    let mut title = parts.next().unwrap_or("").trim().to_owned();
    if title.is_empty() && consumed == 1 && i + 1 < lines.len() {
        let next = lines[i + 1].trimmed().trim();
        if (next.starts_with('"') && next.ends_with('"') && next.len() >= 2)
            || (next.starts_with('\'') && next.ends_with('\'') && next.len() >= 2)
        {
            title = next.to_owned();
            consumed = 2;
        }
    }
    let title = title
        .trim_matches(|c| c == '"' || c == '\'' || c == '(' || c == ')')
        .to_owned();
    let url = url.trim_matches(|c| c == '<' || c == '>').to_owned();
    Some((label, url, title, consumed))
}

fn find_link_label_end(s: &str) -> Option<usize> {
    let bytes = s.as_bytes();
    if bytes.first() != Some(&b'[') {
        return None;
    }
    let mut depth = 0;
    let mut escaped = false;
    for (idx, b) in bytes.iter().enumerate() {
        if escaped {
            escaped = false;
            continue;
        }
        match b {
            b'\\' => escaped = true,
            b'[' => depth += 1,
            b']' => {
                depth -= 1;
                if depth == 0 {
                    return Some(idx);
                }
            }
            _ => {}
        }
    }
    None
}

fn footnote_def(lines: &[Line], i: usize) -> Option<(String, usize)> {
    let line = lines[i].trimmed();
    if !line.starts_with("[^") {
        return None;
    }
    let close = line.find("]:")?;
    let label = line[2..close].to_owned();
    if label.is_empty() {
        return None;
    }
    let mut consumed = 1;
    let mut j = i + 1;
    while j < lines.len() {
        if lines[j].is_blank() {
            let mut k = j;
            while k < lines.len() && lines[k].is_blank() {
                k += 1;
            }
            if k < lines.len() && lines[k].indent() >= 4 {
                consumed = k - i + 1;
                j = k + 1;
                continue;
            }
            break;
        }
        if lines[j].indent() >= 4 {
            consumed = j - i + 1;
            j += 1;
            continue;
        }
        // A lazy continuation line right after the definition.
        if consumed == j - i && !interrupts_paragraph(lines[j].trimmed()) && footnote_def(lines, j).is_none()
        {
            consumed = j - i + 1;
            j += 1;
            continue;
        }
        break;
    }
    Some((label, consumed))
}

fn table_start(lines: &[Line], i: usize) -> Option<(Vec<Align>, usize)> {
    if i + 1 >= lines.len() {
        return None;
    }
    let head = lines[i].trimmed();
    if !head.contains('|') {
        return None;
    }
    let delim = lines[i + 1].trimmed();
    if !delim.contains('-') {
        return None;
    }
    let cells = raw_cells(delim);
    if cells.is_empty() {
        return None;
    }
    let mut aligns = Vec::new();
    for cell in &cells {
        let c = cell.trim();
        if c.is_empty() {
            return None;
        }
        let left = c.starts_with(':');
        let right = c.ends_with(':');
        let core = c.trim_matches(':');
        if core.is_empty() || !core.chars().all(|x| x == '-') {
            return None;
        }
        aligns.push(match (left, right) {
            (true, true) => Align::Center,
            (true, false) => Align::Left,
            (false, true) => Align::Right,
            (false, false) => Align::None,
        });
    }
    let head_cells = raw_cells(head);
    if head_cells.len() != aligns.len() {
        return None;
    }
    Some((aligns, 2))
}

fn raw_cells(s: &str) -> Vec<String> {
    let mut s = s.trim();
    if s.starts_with('|') {
        s = &s[1..];
    }
    if s.ends_with('|') && !s.ends_with("\\|") {
        s = &s[..s.len() - 1];
    }
    let mut out = Vec::new();
    let mut cur = String::new();
    let mut escaped = false;
    for c in s.chars() {
        if escaped {
            cur.push(c);
            escaped = false;
            continue;
        }
        match c {
            '\\' => {
                escaped = true;
                cur.push('\\');
            }
            '|' => {
                out.push(cur.clone());
                cur.clear();
            }
            _ => cur.push(c),
        }
    }
    out.push(cur);
    out
}

fn split_row(s: &str, ncols: usize) -> Vec<String> {
    let mut cells = raw_cells(s);
    while cells.len() < ncols {
        cells.push(String::new());
    }
    cells.truncate(ncols);
    cells
}

/// Merge adjacent `Str` tokens so the typographic cleaner sees whole runs.
pub fn merge_strings(tokens: &mut Vec<Token>) {
    let mut i = 0;
    while i + 1 < tokens.len() {
        let merge = matches!(
            (&tokens[i], &tokens[i + 1]),
            (Token::Str(_), Token::Str(_))
        );
        if merge {
            let next = tokens.remove(i + 1);
            if let (Token::Str(ref mut a), Token::Str(b)) = (&mut tokens[i], next) {
                a.push_str(&b);
            }
        } else {
            i += 1;
        }
    }
    for token in tokens.iter_mut() {
        if let Some(inner) = token.inner_mut() {
            merge_strings(inner);
        }
    }
}

/// An image alone in its paragraph becomes a standalone image.
fn promote_standalone_images(tokens: &mut [Token]) {
    for token in tokens.iter_mut() {
        if let Token::Paragraph(ref mut inner) = *token {
            let only_image = inner.len() == 1 && matches!(inner[0], Token::Image(..));
            if only_image {
                if let Token::Image(url, title, alt) = inner[0].clone() {
                    inner[0] = Token::StandaloneImage(url, title, alt);
                }
            }
        }
        if let Some(inner) = token.inner_mut() {
            promote_standalone_images(inner);
        }
    }
}

// ---------------------------------------------------------------------------
// Inline parsing
// ---------------------------------------------------------------------------

#[derive(Debug)]
struct Delim {
    ch: char,
    count: usize,
    /// Index in the output vector of the Str token holding the delimiters.
    index: usize,
    can_open: bool,
    can_close: bool,
}

impl Parser {
    pub fn parse_inline(&self, text: &str) -> Vec<Token> {
        let mut out = self.inline_pass(text);
        merge_strings(&mut out);
        out
    }

    fn inline_pass(&self, text: &str) -> Vec<Token> {
        let chars: Vec<char> = text.chars().collect();
        let mut out: Vec<Token> = Vec::new();
        let mut delims: Vec<Delim> = Vec::new();
        let mut i = 0;
        let mut pending = String::new();
        macro_rules! flush {
            () => {
                if !pending.is_empty() {
                    out.push(Token::Str(std::mem::take(&mut pending)));
                }
            };
        }
        while i < chars.len() {
            let c = chars[i];
            match c {
                '\\' if i + 1 < chars.len() && is_ascii_punct(chars[i + 1]) => {
                    pending.push(chars[i + 1]);
                    i += 2;
                }
                '\\' if i + 1 < chars.len() && chars[i + 1] == '\n' => {
                    flush!();
                    out.push(Token::HardBreak);
                    i += 2;
                }
                '`' => {
                    let n = run_length(&chars, i, '`');
                    if let Some(end) = find_code_end(&chars, i + n, n) {
                        flush!();
                        let content: String = chars[i + n..end].iter().collect();
                        let content = normalize_code(&content);
                        out.push(Token::Code(vec![Token::Str(content)]));
                        i = end + n;
                    } else {
                        for _ in 0..n {
                            pending.push('`');
                        }
                        i += n;
                    }
                }
                '\n' => {
                    let trailing = pending.len() - pending.trim_end_matches(' ').len();
                    if trailing >= 2 {
                        let keep = pending.trim_end_matches(' ').to_owned();
                        pending = keep;
                        flush!();
                        out.push(Token::HardBreak);
                    } else {
                        let keep = pending.trim_end_matches(' ').to_owned();
                        pending = keep;
                        flush!();
                        out.push(Token::SoftBreak);
                    }
                    i += 1;
                    // Leading spaces of the next line are stripped.
                    while i < chars.len() && chars[i] == ' ' {
                        i += 1;
                    }
                }
                '&' => {
                    if let Some((decoded, len)) = entities::decode(&chars[i..]) {
                        pending.push_str(&decoded);
                        i += len;
                    } else {
                        pending.push('&');
                        i += 1;
                    }
                }
                '<' => {
                    if let Some((token, len)) = self.autolink(&chars, i) {
                        flush!();
                        out.push(token);
                        i += len;
                    } else if let Some(len) = raw_html_len(&chars, i) {
                        flush!();
                        let raw: String = chars[i..i + len].iter().collect();
                        out.push(Token::Html(raw));
                        i += len;
                    } else {
                        pending.push('<');
                        i += 1;
                    }
                }
                '!' if i + 1 < chars.len() && chars[i + 1] == '[' => {
                    if let Some((token, len)) = self.link(&chars, i, true) {
                        flush!();
                        out.push(token);
                        i += len;
                    } else {
                        pending.push('!');
                        i += 1;
                    }
                }
                '[' => {
                    if chars.get(i + 1) == Some(&'^') {
                        if let Some(end) = chars[i..].iter().position(|&c| c == ']') {
                            let label: String = chars[i + 2..i + end].iter().collect();
                            if !label.is_empty() {
                                flush!();
                                out.push(Token::FootnoteReference(label));
                                i += end + 1;
                                continue;
                            }
                        }
                    }
                    if let Some((token, len)) = self.link(&chars, i, false) {
                        flush!();
                        out.push(token);
                        i += len;
                    } else {
                        pending.push('[');
                        i += 1;
                    }
                }
                '*' | '_' | '~' | '^' => {
                    if c == '^' && !self.features.superscript {
                        pending.push('^');
                        i += 1;
                        continue;
                    }
                    let n = run_length(&chars, i, c);
                    let before = if i == 0 { None } else { Some(chars[i - 1]) };
                    let after = chars.get(i + n).copied();
                    let (can_open, can_close) = flanking(c, before, after);
                    flush!();
                    let s: String = std::iter::repeat(c).take(n).collect();
                    out.push(Token::Str(s));
                    delims.push(Delim {
                        ch: c,
                        count: n,
                        index: out.len() - 1,
                        can_open,
                        can_close,
                    });
                    i += n;
                }
                'h' | 'w' | 'm' if is_autolink_literal_start(&chars, i) => {
                    let (url, len) = read_autolink_literal(&chars, i);
                    flush!();
                    let href = if url.starts_with("www.") {
                        format!("http://{url}")
                    } else {
                        url.clone()
                    };
                    out.push(Token::Link(href, String::new(), vec![Token::Str(url)]));
                    i += len;
                }
                _ => {
                    pending.push(c);
                    i += 1;
                }
            }
        }
        flush!();
        self.process_emphasis(&mut out, &mut delims);
        out
    }

    fn process_emphasis(&self, out: &mut Vec<Token>, delims: &mut Vec<Delim>) {
        // Resolve delimiter pairs from the innermost closer outwards.
        let mut closer_idx = 0;
        while closer_idx < delims.len() {
            if !delims[closer_idx].can_close || delims[closer_idx].count == 0 {
                closer_idx += 1;
                continue;
            }
            let ch = delims[closer_idx].ch;
            let mut opener_idx = None;
            for k in (0..closer_idx).rev() {
                if delims[k].ch == ch && delims[k].can_open && delims[k].count > 0 {
                    // Rule of 3 for `*`/`_`.
                    if (delims[k].can_close || delims[closer_idx].can_open)
                        && (delims[k].count + delims[closer_idx].count) % 3 == 0
                        && delims[k].count % 3 != 0
                    {
                        continue;
                    }
                    opener_idx = Some(k);
                    break;
                }
            }
            let opener_idx = match opener_idx {
                Some(k) => k,
                None => {
                    delims[closer_idx].can_close = false;
                    closer_idx += 1;
                    continue;
                }
            };
            let use_count = match ch {
                '~' | '^' => delims[opener_idx].count.min(delims[closer_idx].count),
                _ => {
                    if delims[opener_idx].count >= 2 && delims[closer_idx].count >= 2 {
                        2
                    } else {
                        1
                    }
                }
            };
            let oi = delims[opener_idx].index;
            let ci = delims[closer_idx].index;
            // Trim the delimiter strings.
            trim_delim(out, oi, use_count);
            trim_delim(out, ci, use_count);
            delims[opener_idx].count -= use_count;
            delims[closer_idx].count -= use_count;
            // Wrap what lies between.
            let inner: Vec<Token> = out[oi + 1..ci].to_vec();
            let wrapped = match ch {
                '*' | '_' => {
                    if use_count >= 2 {
                        Token::Strong(inner)
                    } else {
                        Token::Emphasis(inner)
                    }
                }
                '~' => {
                    if self.features.superscript && use_count == 1 {
                        Token::Subscript(inner)
                    } else {
                        Token::Strikethrough(inner)
                    }
                }
                '^' => Token::Superscript(inner),
                _ => Token::Emphasis(inner),
            };
            let removed = ci - oi - 1;
            out.splice(oi + 1..ci, std::iter::once(wrapped));
            let shift = removed.saturating_sub(1);
            for d in delims.iter_mut() {
                if d.index > oi && d.index >= ci {
                    d.index -= shift;
                }
            }
            // Drop delimiters that were swallowed by the new node.
            for k in (opener_idx + 1)..closer_idx {
                delims[k].count = 0;
                delims[k].can_open = false;
                delims[k].can_close = false;
            }
            if delims[closer_idx].count == 0 {
                closer_idx += 1;
            }
        }
        // Remove now-empty delimiter placeholders.
        out.retain(|t| !matches!(t, Token::Str(s) if s.is_empty()));
        for token in out.iter_mut() {
            if let Some(inner) = token.inner_mut() {
                inner.retain(|t| !matches!(t, Token::Str(s) if s.is_empty()));
            }
        }
    }

    fn autolink(&self, chars: &[char], i: usize) -> Option<(Token, usize)> {
        let close = chars[i..].iter().position(|&c| c == '>')? + i;
        let inner: String = chars[i + 1..close].iter().collect();
        if inner.is_empty() || inner.contains(' ') || inner.contains('<') {
            return None;
        }
        let is_url = inner.contains("://")
            || inner.starts_with("mailto:")
            || inner.starts_with("tel:");
        let is_email = !is_url
            && inner.contains('@')
            && !inner.contains('/')
            && inner.split('@').count() == 2;
        if is_url {
            Some((
                Token::Link(inner.clone(), String::new(), vec![Token::Str(inner)]),
                close - i + 1,
            ))
        } else if is_email {
            Some((
                Token::Link(
                    format!("mailto:{inner}"),
                    String::new(),
                    vec![Token::Str(inner)],
                ),
                close - i + 1,
            ))
        } else {
            None
        }
    }

    fn link(&self, chars: &[char], start: usize, image: bool) -> Option<(Token, usize)> {
        let bracket = if image { start + 1 } else { start };
        let mut depth = 0;
        let mut end = None;
        let mut k = bracket;
        while k < chars.len() {
            match chars[k] {
                '\\' => k += 1,
                '[' => depth += 1,
                ']' => {
                    depth -= 1;
                    if depth == 0 {
                        end = Some(k);
                        break;
                    }
                }
                _ => {}
            }
            k += 1;
        }
        let end = end?;
        let label: String = chars[bracket + 1..end].iter().collect();
        let mut after = end + 1;
        let mut url = String::new();
        let mut title = String::new();
        if chars.get(after) == Some(&'(') {
            let mut depth = 1;
            let mut j = after + 1;
            while j < chars.len() && depth > 0 {
                match chars[j] {
                    '\\' => j += 1,
                    '(' => depth += 1,
                    ')' => depth -= 1,
                    _ => {}
                }
                if depth == 0 {
                    break;
                }
                j += 1;
            }
            if depth != 0 {
                return None;
            }
            let dest: String = chars[after + 1..j].iter().collect();
            let (u, t) = split_dest(&dest);
            url = u;
            title = t;
            after = j + 1;
        } else {
            // Reference link, possibly collapsed or shortcut.
            let mut refname = label.clone();
            if chars.get(after) == Some(&'[') {
                let close = chars[after..].iter().position(|&c| c == ']')? + after;
                let explicit: String = chars[after + 1..close].iter().collect();
                if !explicit.is_empty() {
                    refname = explicit;
                }
                after = close + 1;
            }
            match self.refs.get(&refname.to_lowercase()) {
                Some((u, t)) => {
                    url = u.clone();
                    title = t.clone();
                }
                None => return None,
            }
        }
        let content = self.inline_pass(&label);
        let mut content = content;
        merge_strings(&mut content);
        let token = if image {
            Token::Image(url, title, content)
        } else {
            Token::Link(url, title, content)
        };
        Some((token, after - start))
    }
}

fn split_dest(dest: &str) -> (String, String) {
    let dest = dest.trim();
    if let Some(rest) = dest.strip_prefix('<') {
        if let Some(idx) = rest.find('>') {
            let url = rest[..idx].to_owned();
            let title = rest[idx + 1..].trim();
            return (url, strip_quotes(title));
        }
    }
    // Split on the first whitespace not inside quotes.
    match dest.find(char::is_whitespace) {
        Some(idx) => (
            unescape(&dest[..idx]),
            strip_quotes(dest[idx..].trim()),
        ),
        None => (unescape(dest), String::new()),
    }
}

fn strip_quotes(s: &str) -> String {
    let s = s.trim();
    if s.len() >= 2 {
        let first = s.chars().next().unwrap();
        let last = s.chars().last().unwrap();
        if (first == '"' && last == '"')
            || (first == '\'' && last == '\'')
            || (first == '(' && last == ')')
        {
            return s[1..s.len() - 1].to_owned();
        }
    }
    s.to_owned()
}

fn unescape(s: &str) -> String {
    let mut out = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            if let Some(&n) = chars.peek() {
                if is_ascii_punct(n) {
                    out.push(n);
                    chars.next();
                    continue;
                }
            }
        }
        out.push(c);
    }
    out
}

fn trim_delim(out: &mut [Token], index: usize, count: usize) {
    if let Token::Str(ref mut s) = out[index] {
        let new_len = s.len().saturating_sub(count);
        s.truncate(new_len);
    }
}

fn run_length(chars: &[char], i: usize, c: char) -> usize {
    let mut n = 0;
    while i + n < chars.len() && chars[i + n] == c {
        n += 1;
    }
    n
}

fn find_code_end(chars: &[char], from: usize, n: usize) -> Option<usize> {
    let mut i = from;
    while i < chars.len() {
        if chars[i] == '`' {
            let len = run_length(chars, i, '`');
            if len == n {
                return Some(i);
            }
            i += len;
        } else {
            i += 1;
        }
    }
    None
}

fn normalize_code(s: &str) -> String {
    let s = s.replace('\n', " ");
    if s.len() >= 2 && s.starts_with(' ') && s.ends_with(' ') && s.trim() != "" {
        s[1..s.len() - 1].to_owned()
    } else {
        s
    }
}

fn is_ascii_punct(c: char) -> bool {
    c.is_ascii_punctuation()
}

fn flanking(c: char, before: Option<char>, after: Option<char>) -> (bool, bool) {
    let before_ws = before.map(|c| c.is_whitespace()).unwrap_or(true);
    let after_ws = after.map(|c| c.is_whitespace()).unwrap_or(true);
    let before_punct = before.map(is_punct).unwrap_or(false);
    let after_punct = after.map(is_punct).unwrap_or(false);
    let left_flanking = !after_ws && (!after_punct || before_ws || before_punct);
    let right_flanking = !before_ws && (!before_punct || after_ws || after_punct);
    match c {
        '_' => (
            left_flanking && (!right_flanking || before_punct),
            right_flanking && (!left_flanking || after_punct),
        ),
        _ => (left_flanking, right_flanking),
    }
}

fn is_punct(c: char) -> bool {
    c.is_ascii_punctuation() || (!c.is_alphanumeric() && !c.is_whitespace())
}

fn raw_html_len(chars: &[char], i: usize) -> Option<usize> {
    if chars.get(i) != Some(&'<') {
        return None;
    }
    let rest: String = chars[i..].iter().collect();
    if rest.starts_with("<!--") {
        return rest.find("-->").map(|p| p + 3);
    }
    let after = &rest[1..];
    let after = after.strip_prefix('/').unwrap_or(after);
    if !after.starts_with(|c: char| c.is_ascii_alphabetic()) {
        return None;
    }
    let close = rest.find('>')?;
    let inner = &rest[..close];
    if inner.contains('<') {
        return None;
    }
    Some(close + 1)
}

fn is_autolink_literal_start(chars: &[char], i: usize) -> bool {
    if i > 0 {
        let prev = chars[i - 1];
        if prev.is_alphanumeric() || prev == '/' || prev == ':' || prev == '.' {
            return false;
        }
    }
    let rest: String = chars[i..].iter().take(9).collect();
    rest.starts_with("http://")
        || rest.starts_with("https://")
        || rest.starts_with("www.")
        || rest.starts_with("mailto:")
}

fn read_autolink_literal(chars: &[char], i: usize) -> (String, usize) {
    let mut n = 0;
    while i + n < chars.len() {
        let c = chars[i + n];
        if c.is_whitespace() || c == '<' || c == '>' {
            break;
        }
        n += 1;
    }
    // Trailing punctuation is not part of the link.
    while n > 0 {
        let c = chars[i + n - 1];
        if matches!(c, '.' | ',' | ':' | ';' | '!' | '?' | '"' | '\'' | ')') {
            n -= 1;
        } else {
            break;
        }
    }
    (chars[i..i + n].iter().collect(), n)
}
